  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Brigatinib, which shares the aminopyrimidine–aniline–piperazine scaffold, has an absolute oral bioavailability of 46% in healthy volunteers, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "GSK1322322, another aminopyrimidine–piperazine analogue, achieved 57% absolute oral bioavailability in fasted healthy volunteers, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Imatinib, a piperazine-containing oral kinase inhibitor, has 98% absolute bioavailability, demonstrating that this chemotype can be very well absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Risdiplam, a heteroaromatic piperazine-containing drug, has high oral bioavailability with almost complete absorption and negligible first-pass metabolism, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Niraparib, a structurally related oral drug, has approximately 73% absolute bioavailability in fasted patients, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is palbociclib, whose clinical absolute oral bioavailability is approximately 46% (≥20%). All transferable experimental analogues—brigatinib 46%, GSK1322322 57–77%, imatinib 98%, risdiplam high, and niraparib 73%—consistently support high oral bioavailability. The physicochemical prior predicting low F is overridden by this convergent experimental evidence.",
  "evidence_gaps": [
    "No direct palbociclib absolute bioavailability record is present in the supplied evidence set; the conclusion relies on close analogues and known clinical data.",
    "Record C08 appears to have a SMILES/compound-name mismatch (the shown molecule is not tacrolimus), so it was not weighted heavily.",
    "Most analogues have low Morgan similarity (<0.38), so transferability is moderate; however, the direction is consistent across all reliable records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

